        try:
            import triton as _t
            import triton.language as _tl
            triton, tl = (_t, _tl)

            @triton.jit
            def slot_product(a_ptr, b_ptr, slab_ptr, M, N, K, KC, H, scale_val, BLOCK_M: tl.constexpr, BLOCK_N: tl.constexpr, BLOCK_K: tl.constexpr):
                pid_n = tl.program_id(0)
                pid_m = tl.program_id(1)
                offs_m = pid_m * BLOCK_M + tl.arange(0, BLOCK_M)
                offs_n = pid_n * BLOCK_N + tl.arange(0, BLOCK_N)
                offs_k = tl.arange(0, BLOCK_K)
                for slot in range(0, H):
                    k0 = slot * KC
                    live = k0 < K
                    acc = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)
                    for kk in range(0, tl.cdiv(KC, BLOCK_K)):
                        kv = k0 + kk * BLOCK_K + offs_k
                        k_mask = (kk * BLOCK_K + offs_k < KC) & (kv < K)
                        a_ptrs = a_ptr + offs_m[:, None] * K + kv[None, :]
                        b_ptrs = b_ptr + kv[:, None] * N + offs_n[None, :]
