                        b_tile = tl.load(b_ptrs, mask=k_mask[:, None] & (offs_n[None, :] < N), other=0.0)
                        acc += tl.dot(a_tile, b_tile)
                    slab_ptrs = slab_ptr + (slot * M + offs_m)[:, None] * N + offs_n[None, :]
                    tl.store(slab_ptrs, acc / scale_val, mask=(offs_m[:, None] < M) & live & (offs_n[None, :] < N))

