                        tile = tl.load(ptrs, mask=(offs_r[:, None] < M) & (offs_n[None, :] < N), other=0.0)
                        row_total += tl.sum(tile, axis=0)
                    tl.store(part_ptr + pid_m * N + offs_n, row_total, mask=offs_n < N)
            _RUNTIME = {'triton': triton, 'slot_product': slot_product, 'slab_reduce': slab_reduce}
        except Exception:
            _RUNTIME = False
    return _RUNTIME or None

def _device_ready(tensor):
    global _RUNTIME
    if not str(tensor.device).startswith('npu'):
        return False
    if _build_kernels() is None:
        return False
    try:
        return bool(torch.npu.is_available())
    except Exception:
        return False

def _slab(elements, device):
    return torch.zeros(int(elements), dtype=torch.float32, device=device)

def _torch_run(af, bf, rows, columns, depth, split, scale_val):
    slab = torch.zeros((split, rows, columns), dtype=torch.float32, device=af.device)
    for slot in range(split):
        k0, k1 = slot_bounds(depth, split, slot)
        if k0 >= k1:
            continue
        block = torch.matmul(af[:, k0:k1], bf[k0:k1, :]).to(torch.float32)
        slab[slot] = block / scale_val
    out = slab.sum(dim=0) * scale_val
    partials = slab.sum(dim=1)
    return (out.contiguous(), partials.contiguous())

def run(a, b, g, h, scratch, scale):
    if a.dim() != 2 or b.dim() != 2:
        raise ValueError('a and b must be 2-D')
    if int(a.shape[1]) != int(b.shape[0]):
        raise ValueError('reduction extents of a and b disagree')
    rows, depth = (int(a.shape[0]), int(a.shape[1]))
    columns = int(b.shape[1])
    split = int(scratch.shape[0])
    if split < 1:
        raise ValueError('the slot count must be positive')
    if int(scale) < 1:
        raise ValueError('scale must be a positive integer')
    af = a.to(torch.float32).contiguous()
    bf = b.to(torch.float32).contiguous()
    scale_val = float(int(scale))
    del g, h
    runtime = _build_kernels() if _device_ready(af) else None
    if runtime is None:
        return _torch_run(af, bf, rows, columns, depth, split, scale_val)
    triton = runtime['triton']
    kc = chunk_of(depth, split)
    out = torch.empty((rows, columns), dtype=torch.float32, device=af.device)
    partials = torch.empty((split, columns), dtype=torch.float32, device=af.device)
    slab = _slab(split * rows * columns, af.device)
    runtime['slot_product'][triton.cdiv(columns, _BLOCK_N), triton.cdiv(rows, _BLOCK_M)](af, bf, slab, rows, columns, depth, kc, split, scale_val, _BLOCK_M, _BLOCK_N, _BLOCK_K)
    reduce_rows = max(triton.cdiv(rows, _BLOCK_M), split)
    runtime['slab_reduce'][triton.cdiv(columns, _BLOCK_N), reduce_rows](slab, out, partials, rows, columns, split, scale_val, _BLOCK_M, _BLOCK_N, _BLOCK_R)
    return (out, partials)

from __future__ import annotations
import torch
SCALE = 4.0
try:
    import torch_npu
except Exception:
    pass
try:
    import triton
    import triton.language as tl
    _HAS_TRITON = True
except Exception:
    triton = None
    tl = None
    _HAS_TRITON = False
_LANE_BLOCK_CAP = 8192
_TILE_ELEMENTS = 2048
_MAX_ROW_BLOCK = 8
_PERSISTENT_LANE_CAP = 4096
_DEFAULT_PROGRAMS = 40
_CORES = None
if _HAS_TRITON:

    @triton.jit
    def _reduce_band(X, BIAS, OUT, MOD, OFF, PIVOT, LOGIT, TEMP, NROWS, rows, lane, lane_ok, lane_res, bias, NC: tl.constexpr):
        want = OFF - rows % MOD
        want = tl.where(want < 0, want + MOD, want)
        live = ((lane_res[None, :] == want[:, None]) | (lane[None, :] == PIVOT)) & lane_ok[None, :]
        row_ok = rows < NROWS
        offsets = rows[:, None] * NC + lane[None, :]
        tile = tl.load(X + offsets, mask=row_ok[:, None] & lane_ok[None, :], other=0.0)
        z = tile * TEMP
        peak = tl.max(tl.where(live, z, -1e+30), 1)
        w = tl.where(live, tl.exp(z - peak[:, None]), 0.0)
        pooled = tl.sum(w * bias[None, :], 1) / tl.sum(w, 1)
        tl.store(OUT + rows, pooled * LOGIT, mask=row_ok)

    @triton.jit
    def _gated_row_softmax_kernel(X, BIAS, OUT, MOD, OFF, PIVOT, LOGIT, TEMP, NROWS, NC: tl.constexpr, BR: tl.constexpr, BL: tl.constexpr):
        pid = tl.program_id(0)
        rows = pid * BR + tl.arange(0, BR)
        lane = tl.arange(0, BL)
        lane_ok = lane < NC
        row_ok = rows < NROWS
        want = OFF - rows % MOD
        want = tl.where(want < 0, want + MOD, want)
        live = ((lane[None, :] % MOD == want[:, None]) | (lane[None, :] == PIVOT)) & lane_ok[None, :]
        offsets = rows[:, None] * NC + lane[None, :]
        tile = tl.load(X + offsets, mask=row_ok[:, None] & lane_ok[None, :], other=0.0)
        z = tile * TEMP
        peak = tl.max(tl.where(live, z, -1e+30), 1)
        w = tl.where(live, tl.exp(z - peak[:, None]), 0.0)
        bias = tl.load(BIAS + lane, mask=lane_ok, other=0.0)
        pooled = tl.sum(w * bias[None, :], 1) / tl.sum(w, 1)
        tl.store(OUT + rows, pooled * LOGIT, mask=row_ok)

    @triton.jit
    def _gated_row_softmax_persistent(X, BIAS, OUT, MOD, OFF, PIVOT, LOGIT, TEMP, NROWS, NC: tl.constexpr, BR: tl.constexpr, BL: tl.constexpr, NPROG: tl.constexpr):
        pid = tl.program_id(0)
        lane = tl.arange(0, BL)
        lane_ok = lane < NC
        lane_res = lane % MOD
        bias = tl.load(BIAS + lane, mask=lane_ok, other=0.0)
        for band in range(pid, tl.cdiv(NROWS, BR), NPROG):
            rows = band * BR + tl.arange(0, BR)
            _reduce_band(X, BIAS, OUT, MOD, OFF, PIVOT, LOGIT, TEMP, NROWS, rows, lane, lane_ok, lane_res, bias, NC)

def _lane_block(lanes: int) -> int:
    block = 1 << max(0, (lanes - 1).bit_length())
    return min(block, _LANE_BLOCK_CAP)

def _row_block(rows: int, lanes: int, lane_block: int) -> int:
    limit = max(1, _TILE_ELEMENTS // max(1, lane_block))
    block = min(_MAX_ROW_BLOCK, limit, max(1, rows))
    return 1 << max(0, block.bit_length() - 1)

def _program_count(bands: int) -> int:
    global _CORES
    if _CORES is None:
        _CORES = _DEFAULT_PROGRAMS
        try:
            utils = triton.runtime.driver.active.utils
            props = utils.get_device_properties('npu:0')
            _CORES = int(props.get('num_vectorcore', _CORES)) or _CORES
        except Exception:
            pass
    return max(1, min(_CORES, bands))

def _on_triton_device(x: torch.Tensor) -> bool:
    if not _HAS_TRITON:
        return False
    device_type = getattr(x.device, 'type', '')
    if device_type == 'npu':
        return bool(getattr(torch, 'npu', None) is not None and torch.npu.is_available())
    if device_type == 'cuda':
        return bool(torch.cuda.is_available())
    return False

def _decode(params):
    keep_modulus, keep_offset, pivot_raw, logit_raw, temp_raw = params.tolist()
    return (int(keep_modulus), int(keep_offset), int(pivot_raw), float(logit_raw) / SCALE, float(temp_raw) / SCALE)

def _eager(x, bias, params):
    lead = tuple(x.shape)[:-1]
    lanes = int(x.shape[-1])
    rows = x.numel() // lanes
    keep_modulus, keep_offset, pivot_raw, logit, temp = _decode(params)
    pivot = pivot_raw % lanes
    if rows == 0:
        return torch.empty(lead, dtype=torch.float32, device=x.device)
    tile = x.reshape(rows, lanes)
    index = torch.arange(rows, dtype=torch.int64, device=x.device).unsqueeze(1)
    lane = torch.arange(lanes, dtype=torch.int64, device=x.device).unsqueeze(0)
    keep = ((index + lane) % keep_modulus == keep_offset) | (lane == pivot)
    z = tile * temp
    peak = torch.where(keep, z, torch.full_like(z, -1e+30)).max(dim=1, keepdim=True).values
    w = torch.where(keep, torch.exp(z - peak), torch.zeros_like(z))
    pooled = torch.sum(w * bias.unsqueeze(0), dim=1) / torch.sum(w, dim=1)
    return (pooled * logit).reshape(lead)

def run(x: torch.Tensor, bias: torch.Tensor, params: torch.Tensor) -> torch.Tensor:
    lead = tuple(x.shape)[:-1]
    lanes = int(x.shape[-1])
    rows = x.numel() // lanes
    if rows == 0:
        return torch.empty(lead, dtype=torch.float32, device=x.device)
    if not (_HAS_TRITON and _on_triton_device(x)):
        return _eager(x, bias, params)
    keep_modulus, keep_offset, pivot_raw, logit, temp = _decode(params)
    pivot = pivot_raw % lanes
    lane_block = _lane_block(lanes)
    row_block = _row_block(rows, lanes, lane_block)
    out = torch.empty(rows, dtype=torch.float32, device=x.device)
    args = (x, bias, out, keep_modulus, keep_offset, pivot, logit, temp, rows)
    bands = (rows + row_block - 1) // row_block
    programs = _program_count(bands)
    if lane_block <= _PERSISTENT_LANE_CAP and programs > 1:
        _gated_row_softmax_persistent[programs,](*args, NC=lanes, BR=row_block, BL=lane_block, NPROG=programs)
    else:
        _gated_row_softmax_kernel[bands,](*args, NC=lanes, BR=row_block, BL=lane_block)
    return out.view(lead)
